import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"协作与变更流程","description":"用 GitHub 管理办公室智能化项目中的文档、任务和决策。","frontmatter":{"title":"协作与变更流程","description":"用 GitHub 管理办公室智能化项目中的文档、任务和决策。"},"headers":[],"relativePath":"guide/workflow.md","filePath":"guide/workflow.md","lastUpdated":1785475798000}'),r={name:"guide/workflow.md"};function i(l,t,c,s,n,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="协作与变更流程" tabindex="-1">协作与变更流程 <a class="header-anchor" href="#协作与变更流程" aria-label="Permalink to &quot;协作与变更流程&quot;">​</a></h1><h2 id="三个对象" tabindex="-1">三个对象 <a class="header-anchor" href="#三个对象" aria-label="Permalink to &quot;三个对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>用途</th><th>示例</th></tr></thead><tbody><tr><td>Markdown 文档</td><td>稳定的方案、规范、记录</td><td>网络方案、设备台账、运维手册</td></tr><tr><td>GitHub Issue</td><td>一项待决、待做或待验收的工作</td><td>采购会议室传感器、修复 AP 覆盖盲区</td></tr><tr><td>Pull Request</td><td>对文档/配置的可审核变更</td><td>合并新的 VLAN 规划与交换机配置</td></tr></tbody></table><h2 id="推荐状态" tabindex="-1">推荐状态 <a class="header-anchor" href="#推荐状态" aria-label="Permalink to &quot;推荐状态&quot;">​</a></h2><p><code>想法 → 待评审 → 已批准 → 执行中 → 待验收 → 已完成</code></p><p>以下情况必须新建 Issue：新增费用、改变设备型号、变更布线/电力、自动化规则变更、现场发现问题、验收不通过。</p><h2 id="github-projects-字段" tabindex="-1">GitHub Projects 字段 <a class="header-anchor" href="#github-projects-字段" aria-label="Permalink to &quot;GitHub Projects 字段&quot;">​</a></h2><p>在组织级 Project 建立以下字段：</p><ul><li><code>状态</code>：想法、待评审、已批准、执行中、待验收、已完成</li><li><code>区域</code>：前台、办公区、会议室、机房/弱电间、公共区</li><li><code>系统</code>：网络、照明、环境、安防、影音、自动化、文档</li><li><code>预算</code> 与 <code>实际金额</code></li><li><code>计划完成日</code>、<code>负责人</code>、<code>供应商</code></li></ul><p>GitHub Projects 可把相同项目数据切换为表格、看板和路线图，因此无需复制多份进度表。<a href="https://docs.github.com/en/issues/planning-and-tracking-with-projects" target="_blank" rel="noreferrer">GitHub 官方说明</a></p><h2 id="提交约定" tabindex="-1">提交约定 <a class="header-anchor" href="#提交约定" aria-label="Permalink to &quot;提交约定&quot;">​</a></h2><ul><li>一个 Pull Request 聚焦一个可描述的变更。</li><li>现场照片、设备型号、Issue 编号写入提交说明或文档。</li><li>合并前至少由一位了解现场的人复核。</li><li>不提交密码、密钥、门禁凭证和个人敏感信息。</li></ul>',12)])])}const p=e(r,[["render",i]]);export{b as __pageData,p as default};
